CAT = "cacesStabilite"; SEG = "STA"
# Notions de physique et stabilité : masse, centre de gravité, moments, renversement latéral,
# basculement avant, position de la charge. Sources : R489 annexe 2 (D, E) et annexe 3/1 ;
# INRS ED 766, § 2.3, 2.5, 3.5 ; INRS ED 949, § 2.4 ; INRS ED 812.
Q = [
("Où se trouve le plus souvent le centre de gravité d'une charge homogène sur palette ?",
 "Au milieu", ["Contre le tablier", "Au bout des fourches", "Sous la palette"],
 "INRS ED 766, § 2.3 : on ne lève jamais une charge sans connaître la distance entre son centre de gravité, souvent situé au milieu de la charge, et la face avant des bras de fourche."),
("Plus le centre de gravité de la charge s'éloigne du talon des fourches, plus la capacité du chariot :",
 "Diminue", ["Augmente", "Reste la même", "Double"],
 "INRS ED 766, § 2.3 : le poids que peut porter le chariot diminue quand la distance entre le centre de gravité de la charge et la face avant des fourches augmente."),
("Un chariot frontal bascule vers l'avant. Quelle est la cause la plus probable ?",
 "Une charge trop lourde", ["Un virage trop serré", "Un sol trop adhérent", "Une batterie trop chargée"],
 "R489, annexe 3/1 : la surcharge et un centre de gravité trop éloigné font pivoter le chariot autour de l'essieu avant ; le virage rapide cause plutôt un renversement latéral."),
("Quelle situation favorise le plus le renversement latéral d'un chariot ?",
 "Virer vite fourche haute", ["Freiner doucement en ligne", "Rouler à vide fourche basse", "Gerber à l'arrêt"],
 "INRS ED 949, § 2.4 : les principales causes de renversement latéral sont la vitesse, le virage rapide et la circulation fourche haute, auxquels s'ajoutent obstacles, charge instable et pente."),
("Pourquoi circule-t-on fourche basse, à environ 15 cm du sol ?",
 "Garder un centre de gravité bas", ["Mieux voir le sol devant soi", "Ménager la batterie", "Pouvoir rouler plus vite"],
 "INRS ED 766, § 3.5 : circuler fourche basse, mât incliné en arrière, garde le centre de gravité de l'ensemble bas et limite le risque de renversement."),
("Le chariot commence à se renverser sur le côté. Quel réflexe faut-il avoir ?",
 "Rester dans le poste, tenu", ["Sauter du côté de l'accès", "Sauter côté opposé", "Lâcher le volant et sortir"],
 "INRS ED 949, § 2.4 : le cariste qui saute est souvent écrasé par le toit de protection ou le mât. Ceinturé ou derrière son portillon, on reste au poste et on se tient fermement."),
("Pourquoi incliner le mât en arrière après avoir pris la charge ?",
 "Caler la charge", ["Monter la charge plus vite", "Alléger l'essieu arrière", "Mieux voir sous la fourche"],
 "INRS ED 766, § 2.5 : on engage les fourches à fond, on lève légèrement puis on incline le mât en arrière pour que la charge repose contre le tablier et ne glisse pas."),
("Pourquoi engager les fourches à fond sous la charge ?",
 "Rapprocher la charge du mât", ["Protéger le dessous de la palette", "Pouvoir aller plus vite", "Économiser la batterie"],
 "INRS ED 766, § 2.5 : engager les bras à fond rapproche la charge du tablier, donc son centre de gravité, et préserve la capacité du chariot."),
("Ajouter un poids au contrepoids pour lever plus lourd est :",
 "Interdit dans tous les cas", ["Permis si c'est provisoire", "Permis avec l'accord du chef", "Permis avec un collègue assis"],
 "INRS ED 766, § 2.5 et 3.9 : il est interdit d'augmenter le contrepoids, par un poids ou une personne à l'arrière, pour lever plus que la capacité du constructeur."),
("Vous levez une charge en hauteur, mât incliné vers l'avant. Quel risque augmente ?",
 "Le basculement avant", ["L'échauffement moteur", "L'usure des pneus", "La décharge batterie"],
 "R489, annexe 2 (E) : incliner le mât en avant éloigne le centre de gravité de la charge vers l'avant ; en hauteur, cela favorise le basculement frontal. L'inclinaison avant ne sert qu'à poser."),
("Pourquoi ne déplace-t-on pas une charge levée en hauteur ?",
 "Le chariot devient instable", ["La charge échauffe le mât", "Les fourches s'écartent seules", "Le frein de service se bloque"],
 "INRS ED 766, § 3.5 : il est interdit de circuler fourche haute ; une charge haute monte le centre de gravité et rend le chariot instable dans les virages et au freinage."),
("Quel effet a un sol en pente sur la stabilité latérale ?",
 "Il la diminue", ["Il l'améliore", "Il n'en a aucun", "Il la double"],
 "INRS ED 949, § 2.4 : la déclivité figure parmi les causes de renversement ; un dévers déplace le centre de gravité vers le côté bas."),
("Un trou dans le sol est sur votre trajet, chariot chargé. Quel est le danger principal ?",
 "Renverser le chariot", ["Crever un pneu", "Décharger la batterie", "Tordre le dosseret"],
 "INRS ED 949, § 2.4 : la circulation sur obstacle et l'état du sol (trou, sol instable) font partie des causes recensées de renversement."),
("Une charge est décentrée sur un côté des fourches. Quel est le risque ?",
 "Chute ou renversement", ["Usure du frein", "Surchauffe du moteur", "Aucun si on roule doucement"],
 "INRS ED 766, § 3.9 : il est interdit de lever une charge mal équilibrée ; décentrée, elle peut tomber ou déplacer le centre de gravité de l'ensemble vers le côté."),
("Une charge ne repose que sur un seul bras de fourche. Que faites-vous ?",
 "Je la reprends sur les deux bras", ["Je la lève lentement", "Je la lève à moins de 1 m", "J'incline le mât en arrière"],
 "INRS ED 766, § 3.9 : il est interdit de lever une charge avec un seul bras de fourche : elle est déséquilibrée et peut tomber."),
("Un big-bag est suspendu à un bras de fourche levé. Pourquoi est-ce dangereux ?",
 "Il se balance", ["Il use le bras de fourche", "Il cache le tableau de bord", "Il fait baisser la vitesse"],
 "INRS ED 949, § 2.4 : le balancement du big-bag et la circulation fourche haute augmentent le porte-à-faux ; on utilise des supports conçus pour les big-bags."),
("Deux chariots soulèvent ensemble une charge lourde. Comment l'INRS juge-t-il cette manœuvre ?",
 "Dangereuse, à proscrire", ["Conseillée au-delà de 2 t", "Permise avec un chef de manœuvre", "Permise à moins de 5 km/h"],
 "INRS ED 766, § 2.5 : l'utilisation simultanée de deux chariots pour manutentionner une charge lourde ou encombrante est une manœuvre dangereuse à proscrire."),
("Une charge large peut basculer de la fourche. Que vérifiez-vous avant de rouler ?",
 "Qu'elle ne peut pas basculer", ["Que les phares fonctionnent", "Que le klaxon fonctionne", "Que la batterie est pleine"],
 "INRS ED 766, § 2.5 : si la charge est large, on s'assure qu'elle ne peut pas basculer de la fourche ; au besoin on la cale ou on l'arrime."),
("Pourquoi aborder un virage à faible vitesse avec un chariot ?",
 "Limiter la force centrifuge", ["Économiser les pneus", "Laisser la batterie refroidir", "Éviter le basculement avant"],
 "INRS ED 766, § 3.5 : on aborde les virages à faible vitesse ; la force qui pousse vers l'extérieur croît avec la vitesse et peut renverser le chariot sur le côté."),
("Vous freinez brutalement en marche avant, chargé. Que risque surtout la charge ?",
 "Tomber vers l'avant", ["Glisser vers le tablier", "Monter le long du mât", "Rester bien en place"],
 "INRS ED 766, § 3.5 et 3.9 : il est interdit de freiner brusquement ; l'inertie de la charge reporte le poids vers l'avant et peut faire basculer le chariot ou tomber la charge."),
("Sur un chariot à suspension en trois points, où doit rester le centre de gravité de l'ensemble ?",
 "Dans le triangle d'appui", ["Sur l'essieu arrière", "Au-dessus du mât levé", "Devant les roues avant"],
 "R489, annexe 2 (E) : le chariot reste stable tant que le centre de gravité de l'ensemble chariot et charge reste à l'intérieur de sa base d'appui ; sur trois appuis, c'est un triangle."),
("Le centre de gravité de l'ensemble chariot et charge monte quand :",
 "On lève la charge", ["On baisse la fourche", "On rétracte le mât", "On ralentit"],
 "R489, annexe 2 (E) : lever la charge monte le centre de gravité de l'ensemble ; le chariot devient plus sensible aux virages, aux pentes et aux freinages."),
("Deux charges ont la même masse. Laquelle réduit le plus la capacité du chariot ?",
 "La plus longue vers l'avant", ["La plus étroite", "La mieux filmée", "La plus compacte"],
 "R489, annexe 2 (D, E) et INRS ED 766, § 2.3 : à masse égale, la charge la plus longue dans le sens des fourches a son centre de gravité plus loin du talon, ce qui réduit la capacité."),
("Où trouvez-vous la masse d'une charge à manutentionner ?",
 "Sur l'étiquette ou le bon", ["Sur la plaque du chariot", "Sur le tableau de bord", "Sur le plan de circulation"],
 "R489, annexe 2 (D) : le cariste évalue la masse des charges qu'il manutentionne, à partir des indications portées sur le colis ou les documents de livraison."),
]
